def _mk(n,q,opts,ans,expl,seed,extra=None):
    o,_=shuffle(opts,ans,seed); d={"n":n,"question_zh":q,"options":o,"answer":ans,"explanation_mn":expl}
    if extra: d.update(extra)
    return d
def _ST(n,q,opts,ans,expl,seed): return {"n":n,"question_zh":q,"options":list(opts),"answer":ans,"explanation_mn":expl}
def RD(n,q,ques,opts,ans,expl,seed): return {"n":n,"question_zh":q+"\n★ "+ques,"options":list(opts),"answer":ans,"explanation_mn":expl}
def SO(n,words,ans,dis,expl,seed): return _mk(n,words,[ans]+dis,ans,expl,seed)
def LF(n,s,wrong,right,others,expl,seed): return _mk(n,s+" — аль ханз буруу вэ?",[wrong]+others,wrong,expl,seed)
MPICS=["Эмэгтэй ариун цэврийн цаасаар тоглосон муурыг хараад уурласан байна","Охин, хүү хоёр баяртайгаар ярьж байна","Туулай маш хурдан гүйж байна","Яст мэлхий маш удаан мөлхөж байна","Гурван хүүхэд хятад хэлний ангиас гарч ирж байна","Цүнхтэй хүү өрөөнд гүйж орж байна"]
def MM(n,q,k,expl,seed): return _mk(n,q,MPICS,MPICS[int(k)],expl,seed)
